def arayuz_icin_cevir(metin, dil):
    if dil == "EN": return CSV_CEVIRI.get(metin, metin)
    return metin

def veritabani_icin_cevir(secilen_metin, dil):
    if dil == "EN":
        for tr_isim, en_isim in CSV_CEVIRI.items():
            if en_isim == secilen_metin: return tr_isim
    return secilen_metin

def generate_pdf_bytes(report_string):
    tr_chars = {
        'ı':'i','İ':'I','ğ':'g','Ğ':'G','ü':'u','Ü':'U',
        'ş':'s','Ş':'S','ö':'o','Ö':'O','ç':'c','Ç':'C',
        '₺':'TL','€':'EUR'
    }
    for k, v in tr_chars.items():
        report_string = report_string.replace(k, v)
    pdf = FPDF()
    pdf.add_page()
    pdf.set_font("Arial", size=11)
    for line in report_string.split('\n'):
        clean_line = line.encode('latin-1', 'ignore').decode('latin-1')
        pdf.multi_cell(0, 7, txt=clean_line)
    pdf_output = pdf.output(dest='S')
    if isinstance(pdf_output, str):
        return pdf_output.encode('latin-1')
    return bytes(pdf_output)

