def extract_score_and_verdict(text: str):
    match = re.search(r"(\d{1,3})\s*/\s*100", text)
    if not match: return None, None
    score = max(0, min(int(match.group(1)), 100))
    tail = text[match.end():]
    
    lines = [line.strip() for line in tail.split('\n') if line.strip()]
    if lines:
        verdict = re.sub(r"^[\s\.\:\*\-]+", "", lines[0]).strip()
    else:
        verdict = None
        
    return score, verdict

