def render_score_gauge(score: int, verdict: Optional[str]) -> None:
    font_col = "#F8FAFC" if st.session_state.dark_mode else "#0F172A"
    bg_col = "rgba(0,0,0,0)"

    bar_color = "#10B981" if score >= 75 else ("#F59E0B" if score >= 50 else "#EF4444")
    
    fig = go.Figure(go.Indicator(
        mode = "gauge+number", value = score, domain = {'x': [0, 1], 'y': [0, 1]},
        title = {'text': _["kpi_score"], 'font': {'size': 18, 'color': font_col, 'family': 'Nunito Sans'}},
        gauge = {
            'axis': {'range': [None, 100], 'tickwidth': 1, 'tickcolor': font_col},
            'bar': {'color': bar_color}, 
            'bgcolor': "rgba(255,255,255,0.1)" if st.session_state.dark_mode else "white", 
            'borderwidth': 2, 
            'bordercolor': "rgba(255,255,255,0.2)" if st.session_state.dark_mode else "#E2E8F0",
            'steps': [
                {'range': [0, 50], 'color': "rgba(239, 68, 68, 0.1)"},
                {'range': [50, 75], 'color': "rgba(245, 158, 11, 0.1)"},
                {'range': [75, 100], 'color': "rgba(16, 185, 129, 0.1)"}],
            'threshold': {'line': {'color': font_col, 'width': 3}, 'thickness': 0.75, 'value': score}
        }
    ))
    
    fig.update_layout(height=280, margin=dict(l=20, r=20, t=50, b=20), paper_bgcolor=bg_col, font=dict(color=font_col))
    st.plotly_chart(fig, use_container_width=True)
    
    verdict_html = verdict if verdict else _["score_detail"]
    text_col = "#CBD5E1" if st.session_state.dark_mode else "#64748B"
    st.markdown(f"<div style='text-align: center; color: {text_col}; font-size: 0.95rem; margin-top: 10px;'><strong>{_['score_reason']}:</strong> {verdict_html}</div>", unsafe_allow_html=True)


def render_comparison_charts(secilen_karbon, ort_karbon, secilen_su, ort_su):
    c1, c2 = st.columns(2)
    font_col = "#F8FAFC" if st.session_state.dark_mode else "#0F172A"
    bg_col = "rgba(0,0,0,0)"

    with c1:
        renk_k = "#10B981" if secilen_karbon <= ort_karbon else "#EF4444"
        fig_k  = go.Figure(data=[
            go.Bar(name=_['avg_label'], x=['CO2 (kg)'], y=[ort_karbon],
                   marker_color='#94A3B8', text=[f"{int(ort_karbon)}"], textposition='auto'),
            go.Bar(name=_['sel_label'], x=['CO2 (kg)'], y=[secilen_karbon],
                   marker_color=renk_k, text=[f"{int(secilen_karbon)}"], textposition='auto')
        ])
        fig_k.update_layout(
            barmode='group',
            title={'text':_['comp_c_title'],'font':{'size':14,'color':font_col,'family':'Alte Haas Grotesk'}},
            height=280, margin=dict(t=70,b=40,l=10,r=10), paper_bgcolor=bg_col, plot_bgcolor=bg_col,
            showlegend=True, legend=dict(orientation="h",yanchor="top",y=-0.15,xanchor="center",x=0.5, font=dict(color=font_col))
        )
        fig_k.update_xaxes(tickfont=dict(color=font_col))
        fig_k.update_yaxes(tickfont=dict(color=font_col), gridcolor="rgba(148, 163, 184, 0.2)")
        st.plotly_chart(fig_k, use_container_width=True)
        
    with c2:
        renk_s = "#3B82F6" if secilen_su <= ort_su else "#EF4444"
        fig_s  = go.Figure(data=[
            go.Bar(name=_['avg_label'], x=['H2O (L)'], y=[ort_su],
                   marker_color='#94A3B8', text=[f"{int(ort_su)}"], textposition='auto'),
            go.Bar(name=_['sel_label'], x=['H2O (L)'], y=[secilen_su],
                   marker_color=renk_s, text=[f"{int(secilen_su)}"], textposition='auto')
        ])
        fig_s.update_layout(
            barmode='group',
            title={'text':_['comp_w_title'],'font':{'size':14,'color':font_col,'family':'Alte Haas Grotesk'}},
            height=280, margin=dict(t=70,b=40,l=10,r=10), paper_bgcolor=bg_col, plot_bgcolor=bg_col, showlegend=False
        )
        fig_s.update_xaxes(tickfont=dict(color=font_col))
        fig_s.update_yaxes(tickfont=dict(color=font_col), gridcolor="rgba(148, 163, 184, 0.2)")
        st.plotly_chart(fig_s, use_container_width=True)


